{
  "chat_title": "小店进货群",
  "is_group": true,
  "messages": [
    {
      "sender": "郑楠",
      "is_self": false,
      "time": "21:28",
      "text": "云南那家豆子报价发你了，每公斤126元，起订20公斤",
      "kind": "text"
    },
    {
      "sender": "我",
      "is_self": true,
      "time": "",
      "text": "上次不是120吗？涨了？",
      "kind": "text"
    },
    {
      "sender": "郑楠",
      "is_self": false,
      "time": "",
      "text": "说是新产季，水洗的涨了6元",
      "kind": "text"
    },
    {
      "sender": "罗佳宁",
      "is_self": false,
      "time": "22:10",
      "text": "我问了另一家，日晒的123元/公斤，含运费",
      "kind": "text"
    },
    {
      "sender": "我",
      "is_self": true,
      "time": "22:33",
      "text": "那两家各要5公斤试试，周一前定下来",
      "kind": "text"
    },
    {
      "sender": "郑楠",
      "is_self": false,
      "time": "",
      "text": "好，我跟他说周一发货",
      "kind": "text"
    }
  ]
}

{
  "chat_title": "袁野",
  "is_group": false,
  "messages": [
    {
      "sender": "野",
      "is_self": false,
      "time": "11:53",
      "text": "周四晚上聚餐定在哪?",
      "kind": "text"
    },
    {
      "sender": "我",
      "is_self": true,
      "time": "",
      "text": "就学校东门那家，9个人",
      "kind": "text"
    },
    {
      "sender": "野",
      "is_self": false,
      "time": "",
      "text": "我订了19:00的包间，人均大概85元",
      "kind": "text"
    },
    {
      "sender": "我",
      "is_self": true,
      "time": "",
      "text": "好的，我跟大家说一声",
      "kind": "text"
    },
    {
      "sender": "野",
      "is_self": false,
      "time": "11:58",
      "text": "[图片]",
      "kind": "image"
    },
    {
      "sender": "野",
      "is_self": false,
      "time": "",
      "text": "这是菜单，你看看要不要加菜",
      "kind": "text"
    }
  ]
}

{
  "chat_title": "三年二班家长群",
  "is_group": true,
  "messages": [
    {
      "sender": "蒋南",
      "is_self": false,
      "time": "20:51",
      "text": "各位家长：8月5日秋游，7:40在校门口集合，请带水和午餐",
      "kind": "text"
    },
    {
      "sender": "林欣",
      "is_self": false,
      "time": "",
      "text": "需要另外交费吗？",
      "kind": "text"
    },
    {
      "sender": "蒋南",
      "is_self": false,
      "time": "",
      "text": "车费每人45元，已从班费扣除",
      "kind": "text"
    },
    {
      "sender": "我",
      "is_self": true,
      "time": "",
      "text": "收到，谢谢老师",
      "kind": "text"
    },
    {
      "sender": "冯晨",
      "is_self": false,
      "time": "20:58",
      "text": "请问下雨还去吗",
      "kind": "text"
    },
    {
      "sender": "蒋南",
      "is_self": false,
      "time": "",
      "text": "如遇下雨顺延一周，另行通知",
      "kind": "text"
    }
  ]
}

{
  "chat_title": "采购对接群",
  "is_group": true,
  "messages": [
    {
      "sender": "王晓林",
      "is_self": false,
      "time": "18:36",
      "text": "样品5件已寄出，单号YD690860200102",
      "kind": "text"
    },
    {
      "sender": "王晓林",
      "is_self": false,
      "time": "19:17",
      "text": "我这边还没开发票，金额是2380元对吧？",
      "kind": "text"
    },
    {
      "sender": "我",
      "is_self": true,
      "time": "19:26",
      "text": "对，是2380元，样品我收到后再确认",
      "kind": "text"
    },
    {
      "sender": "王晓林",
      "is_self": false,
      "time": "",
      "text": "好的",
      "kind": "text"
    },
    {
      "sender": "王晓林",
      "is_self": false,
      "time": "19:32",
      "text": "收到，今天下午开",
      "kind": "text"
    }
  ]
}

